// The companion method is generated by the extracted presence generator, not
// a test-specific comparator. The freshness test keeps that execution proof tied
// to the generator used by consumers.
type previousPresenceRow struct {
	ID          *int                 `sqlx:"ID,primaryKey=true"`
	AccountID   *int                 `sqlx:"ACCOUNT_ID"`
	Name        *string              `sqlx:"NAME" invariant:"Content"`
	Quantity    *int                 `sqlx:"QUANTITY" invariant:"Content"`
	Updated     *time.Time           `sqlx:"UPDATED" writer:"audit"`
	UpdatedUser *int                 `sqlx:"UPDATED_USER" writer:"audit"`
	Has         *previousPresenceHas `sqlx:"-" setMarker:"true"`
}
type previousPresenceHas struct{ ID, AccountID, Name, Quantity, Updated, UpdatedUser bool }
type previousPresenceInput struct {
	Rows    []*previousPresenceRow `parameter:"Rows,kind=body,in=data" view:"Rows,table=records"`
	Current []*previousPresenceRow `parameter:"Current,kind=view,in=Current" view:"Current,table=records"`
}
type previousPresenceOutput struct {
	Data         []*previousPresenceRow `parameter:"Data,kind=output,in=body"`
	OriginalName bool
	InitName     bool
}

type previousPresenceNormalize struct{}

func (*previousPresenceNormalize) Init(_ context.Context, row *previousPresenceRow, state xhandler.LifecycleContext[previousPresenceRow, xhandler.NoParent, previousPresenceOutput]) error {
	state.Output.OriginalName = state.Original.Has("Name")
	state.Output.InitName = row.Has != nil && row.Has.Name
	if row.Has != nil && row.Has.Name && row.Name != nil {
		row.Name = ptr(strings.TrimSpace(*row.Name))
	}
	return nil
}

func TestPreviousPresenceGeneratedFixtureIsCurrent(t *testing.T) {
	sources := map[string][]byte{}
	for _, name := range []string{"previous_presence_test.go", "audit_graph_test.go"} {
		source, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		sources[name] = source
	}
	expected, err := presencegen.Generate("writer", sources, []string{"previousPresenceRow", "auditGraphRow", "auditGraphChild"}, presencegen.Options{RowOnly: true})
	if err != nil {
		t.Fatal(err)
	}
	actual, err := os.ReadFile("previous_presence_generated_test.go")
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(actual, expected) {
		t.Fatal("regenerate previous_presence_generated_test.go with presencegen.Generate; do not hand-edit the comparator")
	}
}

// A real SQLite trigger distinguishes no UPDATE from an UPDATE that happens
// to store the same values. Previous is read from the database, and requests
// retain their real incoming markers through the native writer lifecycle.
func TestGeneratedPreviousComparisonSQLite(t *testing.T) {
	for _, tc := range []struct {
		name        string
		value       *string
		marked      bool
		quantity    *int
		quantitySet bool
		insert      bool
		command     bool
		wantWrites  int
	}{
		{name: "equal marked values and keys", value: ptr("stored"), marked: true},
		{name: "normalized equal value", value: ptr(" stored "), marked: true},
		{name: "unmarked different value", value: ptr("different")},
		{name: "real change", value: ptr("changed"), marked: true, wantWrites: 1},
		{name: "explicit null", marked: true, wantWrites: 1},
		{name: "explicit zero", quantity: ptr(0), quantitySet: true, wantWrites: 1},
		{name: "insert retains audit", value: ptr("stored"), marked: true, insert: true, wantWrites: 1},
		{name: "explicit command retains write", value: ptr("stored"), marked: true, command: true, wantWrites: 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := context.Background()
			db := sqlite.New(t)
			if err := db.ExecStatements(ctx,
				"CREATE TABLE records(ID INTEGER PRIMARY KEY, ACCOUNT_ID INTEGER, NAME TEXT, QUANTITY INTEGER, UPDATED TEXT, UPDATED_USER INTEGER)",
				"CREATE TABLE writes(kind TEXT)",
				"INSERT INTO records VALUES(1,7,'stored',9,'2026-01-01T00:00:00Z',3)",
				"CREATE TRIGGER record_updated AFTER UPDATE ON records BEGIN INSERT INTO writes VALUES('update'); END",
				"CREATE TRIGGER record_inserted AFTER INSERT ON records BEGIN INSERT INTO writes VALUES('insert'); END"); err != nil {
				t.Fatal(err)
			}
			var id, account, quantity, user int
			var name, stamp string
			if err := db.DB.QueryRow("SELECT ID,ACCOUNT_ID,NAME,QUANTITY,UPDATED,UPDATED_USER FROM records WHERE ID=1").Scan(&id, &account, &name, &quantity, &stamp, &user); err != nil {
				t.Fatal(err)
			}
			oldTime, err := time.Parse(time.RFC3339, stamp)
			if err != nil {
				t.Fatal(err)
			}
			previous := &previousPresenceRow{ID: &id, AccountID: &account, Name: &name, Quantity: &quantity, Updated: &oldTime, UpdatedUser: &user}
			newTime := oldTime.Add(time.Hour)
			row := &previousPresenceRow{ID: ptr(id), AccountID: ptr(account), Name: tc.value, Quantity: tc.quantity, Updated: &newTime, UpdatedUser: ptr(4),
				Has: &previousPresenceHas{ID: true, AccountID: true, Name: tc.marked, Quantity: tc.quantitySet, Updated: true, UpdatedUser: true}}
			input := &previousPresenceInput{Rows: []*previousPresenceRow{row}, Current: []*previousPresenceRow{previous}}
			if tc.insert {
				row.ID = ptr(2)
			}
			component := unitComponent()
			component.Key.Scope = reflect.TypeFor[previousPresenceRow]().PkgPath()
			component.RootView.EntityHooks = "previousPresenceNormalize"
			if tc.command {
				component.RootView.WriterActionPolicy = updateActionPolicy
			}
			compiled, err := New(component, reflect.TypeFor[previousPresenceInput](), reflect.TypeFor[previousPresenceOutput](), "patch")
			if err != nil {
				t.Fatal(err)
			}
			if compiled.metadata.HookType != reflect.TypeOf(previousPresenceNormalize{}) {
				t.Fatalf("normalization hook was not linked: %v", compiled.metadata.HookType)
			}
			result, err := runSQLiteWriter(t, ctx, db, component, input, &previousPresenceOutput{}, "patch")
			if err != nil {
				t.Fatal(err)
			}
			output := result.(*previousPresenceOutput)
			if output.OriginalName != tc.marked {
				t.Fatal("comparison mutated original request presence")
			}
			if tc.name == "equal marked values and keys" && output.InitName {
				t.Fatal("unchanged field was still marked at Init")
			}
			var writes int
			if err = db.DB.QueryRow("SELECT COUNT(*) FROM writes").Scan(&writes); err != nil {
				t.Fatal(err)
			}
			if writes != tc.wantWrites {
				t.Fatalf("physical writes=%d, want %d", writes, tc.wantWrites)
			}
			var storedName *string
			var storedQuantity *int
			if err = db.DB.QueryRow("SELECT NAME,QUANTITY,UPDATED,UPDATED_USER FROM records WHERE ID=?", *row.ID).Scan(&storedName, &storedQuantity, &stamp, &user); err != nil {
				t.Fatal(err)
			}
			if tc.wantWrites == 0 {
				if stamp != "2026-01-01T00:00:00Z" || user != 3 || storedName == nil || *storedName != "stored" || storedQuantity == nil || *storedQuantity != 9 {
					t.Fatalf("no-op changed persisted data: name=%v qty=%v stamp=%s user=%d", storedName, storedQuantity, stamp, user)
				}
				if !row.Updated.Equal(oldTime) || *row.UpdatedUser != 3 || row.Has.Updated || row.Has.UpdatedUser {
					t.Fatal("no-op response retained new audit values/markers")
				}
			} else {
				if stamp == "2026-01-01T00:00:00Z" || user != 4 {
					t.Fatal("real write lost audit values")
				}
				if tc.marked && (storedName == nil) != (tc.value == nil) {
					t.Fatal("explicit null presence lost")
				}
				if tc.value != nil && tc.marked && (storedName == nil || *storedName != strings.TrimSpace(*tc.value)) {
					t.Fatal("business value was not persisted")
				}
				if tc.quantitySet && (storedQuantity == nil || *storedQuantity != *tc.quantity) {
					t.Fatal("explicit zero presence lost")
				}
			}
		})
	}
}

type partialPreviousRow struct {
	ID          *int
	AccountID   *int
	Name        *string
	Updated     *time.Time
	UpdatedUser *int
}
type partialPreviousInput struct {
	Rows    []*previousPresenceRow `parameter:"Rows,kind=body,in=data" view:"Rows,table=records"`
	Current []*partialPreviousRow  `parameter:"Current,kind=view,in=Current" view:"Current,table=records"`
}

func TestGeneratedPreviousComparisonSQLitePartialProjection(t *testing.T) {
	ctx := context.Background()
	db := sqlite.New(t)
	if err := db.ExecStatements(ctx,
		"CREATE TABLE records(ID INTEGER PRIMARY KEY, ACCOUNT_ID INTEGER, NAME TEXT, QUANTITY INTEGER, UPDATED TEXT, UPDATED_USER INTEGER)",
		"CREATE TABLE writes(id INTEGER)",
		"INSERT INTO records VALUES(1,7,'stored',9,'2026-01-01T00:00:00Z',3)",
		"CREATE TRIGGER record_updated AFTER UPDATE ON records BEGIN INSERT INTO writes VALUES(NEW.ID); END"); err != nil {
		t.Fatal(err)
	}
	old := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	now := old.Add(time.Hour)
	row := &previousPresenceRow{ID: ptr(1), Quantity: nil, Updated: &now, UpdatedUser: ptr(4), Has: &previousPresenceHas{ID: true, Quantity: true, Updated: true, UpdatedUser: true}}
	input := &partialPreviousInput{Rows: []*previousPresenceRow{row}, Current: []*partialPreviousRow{{ID: ptr(1), AccountID: ptr(7), Name: ptr("stored"), Updated: &old, UpdatedUser: ptr(3)}}}
	_, err := runSQLiteWriter(t, ctx, db, unitComponent(), input, &previousPresenceOutput{}, "patch")
	if err != nil {
		t.Fatal(err)
	}
	var count, nulls int
	if err = db.DB.QueryRow("SELECT (SELECT COUNT(*) FROM writes),QUANTITY IS NULL FROM records WHERE ID=1").Scan(&count, &nulls); err != nil {
		t.Fatal(err)
	}
	if count != 1 || nulls != 1 || !row.Has.Quantity {
		t.Fatalf("unloaded Previous was mistaken for a loaded null: writes=%d null=%d", count, nulls)
	}
}

func TestGeneratedPreviousComparisonSQLiteSharedMarker(t *testing.T) {
	ctx := context.Background()
	db := sqlite.New(t)
	if err := db.ExecStatements(ctx,
		"CREATE TABLE records(ID INTEGER PRIMARY KEY, ACCOUNT_ID INTEGER, NAME TEXT, QUANTITY INTEGER, UPDATED TEXT, UPDATED_USER INTEGER)",
		"CREATE TABLE writes(id INTEGER)",
		"INSERT INTO records VALUES(1,7,'stored',9,'2026-01-01T00:00:00Z',3),(2,7,'stored',9,'2026-01-01T00:00:00Z',3)",
		"CREATE TRIGGER record_updated AFTER UPDATE ON records BEGIN INSERT INTO writes VALUES(NEW.ID); END"); err != nil {
		t.Fatal(err)
	}
	old := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	now := old.Add(time.Hour)
	shared := &previousPresenceHas{ID: true, Name: true, Updated: true, UpdatedUser: true}
	first := &previousPresenceRow{ID: ptr(1), Name: ptr("stored"), Updated: &now, UpdatedUser: ptr(4), Has: shared}
	second := &previousPresenceRow{ID: ptr(2), Name: ptr("changed"), Updated: &now, UpdatedUser: ptr(4), Has: shared}
	input := &previousPresenceInput{Rows: []*previousPresenceRow{first, second}, Current: []*previousPresenceRow{
		{ID: ptr(1), Name: ptr("stored"), Updated: &old, UpdatedUser: ptr(3)},
		{ID: ptr(2), Name: ptr("stored"), Updated: &old, UpdatedUser: ptr(3)},
	}}
	_, err := runSQLiteWriter(t, ctx, db, unitComponent(), input, &previousPresenceOutput{}, "patch")
	if err != nil {
		t.Fatal(err)
	}
	var count, id int
	if err = db.DB.QueryRow("SELECT COUNT(*),COALESCE(MIN(id),0) FROM writes").Scan(&count, &id); err != nil {
		t.Fatal(err)
	}
	if count != 1 || id != 2 {
		t.Fatalf("shared marker suppressed real update: count=%d id=%d", count, id)
	}
	if first.Has == second.Has || !shared.Name || !shared.Updated || first.Has.Name || !second.Has.Name {
		t.Fatal("comparison mutated shared request marker")
	}
}

func TestPreviousComparisonDefersNullRowToStructuralValidation(t *testing.T) {
	h, err := New(unitComponent(), reflect.TypeFor[previousPresenceInput](), reflect.TypeFor[previousPresenceOutput](), "patch")
	if err != nil {
		t.Fatal(err)
	}
	record := h.metadata.Root
	p := &Program{previousFields: map[*Record]fieldSet{record: {"Name": true}}}
	entity := reflect.ValueOf((*previousPresenceRow)(nil))
	frame := &Frame{Record: record, Entity: entity, Previous: reflect.ValueOf(&previousPresenceRow{ID: ptr(1), Name: ptr("stored")}), Action: xhandler.WriteUpdate, Fields: &presence{record: record}}
	// A lifecycle can invalidate a previously matched slot. Presence preparation
	// must not mask the later structural validation error with a reflection panic.
	p.synchronizePreviousPresence(frame)
	if err = p.restoreNoopAudit(frame); err != nil {
		t.Fatal(err)
	}
	if err = p.applyInvariants(frame); err != nil {
		t.Fatal(err)
	}
}

func TestPreviousComparisonPreservesRelationAndChildMarkers(t *testing.T) {
	h, err := New(unitComponent(), reflect.TypeFor[auditGraphInput](), reflect.TypeFor[auditGraphOutput](), "patch")
	if err != nil {
		t.Fatal(err)
	}
	record := h.metadata.Root
	child := &auditGraphChild{ID: ptr(2), Name: ptr("changed"), Has: &auditGraphChildHas{ID: true, Name: true, Remove: true}}
	row := &auditGraphRow{ID: ptr(1), Name: ptr("parent"), Children: []*auditGraphChild{child}, Has: &auditGraphHas{ID: true, Name: true, Children: true}}
	previous := &auditGraphRow{ID: ptr(1), Name: ptr("parent"), Children: []*auditGraphChild{child}}
	p := &Program{previousFields: map[*Record]fieldSet{record: {"Name": true}}}
	frame := &Frame{Record: record, Entity: reflect.ValueOf(row), Previous: reflect.ValueOf(previous), Action: xhandler.WriteUpdate, Fields: livePresence(record, reflect.ValueOf(row).Elem())}
	p.synchronizePreviousPresence(frame)
	if row.Has.Name || !row.Has.ID || !row.Has.Children || !child.Has.Name || !child.Has.Remove {
		t.Fatal("parent comparison changed identity, relation, or child control markers")
	}
}
